/**
 * What other features call: open a file in a Workspace's Edit mode, close
 * and cycle tabs, save, and tell the Editor which files agents are changing.
 * Tabs persist per Workspace; a file's editor lives while any tab shows it.
 */
import type { HarnessKind } from "@polaris/protocol";
import {
  closeTab as closeInSet,
  cycleTab,
  movedPath,
  openTab,
  pinTab,
  renameTab,
  type TabSet,
} from "../model/tabs.ts";
import { fileKey, readTabs, workspaceKey, writeTabs } from "../model/drafts.ts";
import {
  configureEditor,
  type EditorConfig,
  isConfigured,
  ensureBuffer,
  keepMine,
  releaseBuffer,
  saveBuffer,
  takeTheirs,
} from "./buffers.ts";
import { editorStore, tabsOf } from "./store.ts";

export interface OpenFileRequest {
  readonly hostKey: string;
  readonly workspaceId: string;
  /** Absolute on the Host, or relative to the Workspace's root. */
  readonly path: string;
  /** 1-based. */
  readonly line?: number;
  readonly column?: number;
  /** A single click in the explorer: replaced by the next preview until edited. */
  readonly preview?: boolean;
}

/** Each Workspace's root as its pane last said, for relative paths and tree watches. */
const roots = new Map<string, string>();

export const setWorkspaceRoot = (hostKey: string, workspaceId: string, root: string) =>
  roots.set(workspaceKey(hostKey, workspaceId), root);

const resolve = (root: string | undefined, path: string) =>
  path.startsWith("/") || root === undefined
    ? path
    : `${root.replace(/\/$/, "")}/${path.replace(/^\.\//, "")}`;

const setTabs = (key: string, update: (set: TabSet) => TabSet) =>
  editorStore.setState((s) => ({ tabs: { ...s.tabs, [key]: update(tabsOf(s, key)) } }));

/** Whether any Workspace still has a tab on this file. */
const shown = (hostKey: string, path: string) =>
  Object.entries(editorStore.getState().tabs).some(
    ([key, set]) => key.startsWith(`${hostKey}\u0000`) && set.tabs.some((t) => t.path === path)
  );

export const closeTab = (hostKey: string, workspaceId: string, path: string) => {
  setTabs(workspaceKey(hostKey, workspaceId), (set) => closeInSet(set, path));

  if (!shown(hostKey, path)) releaseBuffer(fileKey(hostKey, path));
};

/** Makes sure the active tab's file has an editor (after a restart, tabs come back first). */
export const loadTab = (hostKey: string, workspaceId: string, path: string) => {
  const ws = workspaceKey(hostKey, workspaceId);

  ensureBuffer({
    file: { hostKey, workspaceId, path },
    root: roots.get(ws) ?? path.slice(0, path.lastIndexOf("/")),
    line: null,
    column: null,
    onEdit: () => setTabs(ws, (set) => pinTab(set, path)),
    onDirectory: () => closeTab(hostKey, workspaceId, path),
  });
};

/** Opens that arrive before any editor pane has started the Editor; replayed by `startEditor`. */
const early: Array<OpenFileRequest> = [];

export const openFile = (request: OpenFileRequest) => {
  if (!isConfigured()) {
    early.push(request);

    return;
  }

  const { hostKey, workspaceId } = request;
  const ws = workspaceKey(hostKey, workspaceId);
  const root = roots.get(ws);
  const path = resolve(root, request.path);

  setTabs(ws, (set) => {
    const next = openTab(set, path, request.preview ?? false);
    const replaced = set.tabs.find((t) => t.preview && !next.tabs.some((n) => n.path === t.path));

    // The preview this one replaced loses its editor too, unless another Workspace shows it.
    if (replaced !== undefined)
      queueMicrotask(() => {
        if (!shown(hostKey, replaced.path)) releaseBuffer(fileKey(hostKey, replaced.path));
      });

    return next;
  });

  ensureBuffer({
    file: { hostKey, workspaceId, path },
    root: root ?? path.slice(0, path.lastIndexOf("/")),
    line: request.line ?? null,
    column: request.column ?? null,
    onEdit: () => setTabs(ws, (set) => pinTab(set, path)),
    onDirectory: () => closeTab(hostKey, workspaceId, path),
  });
};

export const activateTab = (hostKey: string, workspaceId: string, path: string) =>
  setTabs(workspaceKey(hostKey, workspaceId), (set) =>
    set.tabs.some((t) => t.path === path) ? { ...set, active: path } : set
  );

export const pinFile = (hostKey: string, workspaceId: string, path: string) =>
  setTabs(workspaceKey(hostKey, workspaceId), (set) => pinTab(set, path));

export const cycleTabs = (hostKey: string, workspaceId: string, delta: 1 | -1) =>
  setTabs(workspaceKey(hostKey, workspaceId), (set) => cycleTab(set, delta));

/** A file or folder renamed in the explorer keeps its tabs; their editors reopen at the new paths. */
export const renameFile = (hostKey: string, from: string, to: string) => {
  for (const set of Object.values(editorStore.getState().tabs)) {
    for (const tab of set.tabs) {
      if (movedPath(tab.path, from, to) !== tab.path) releaseBuffer(fileKey(hostKey, tab.path));
    }
  }

  editorStore.setState((s) => ({
    tabs: Object.fromEntries(
      Object.entries(s.tabs).map(([key, set]) => [
        key,
        key.startsWith(`${hostKey}\u0000`) ? renameTab(set, from, to) : set,
      ])
    ),
  }));
};

export const saveFile = (hostKey: string, path: string) => saveBuffer(fileKey(hostKey, path));

export const keepMyEdits = (hostKey: string, path: string) => keepMine(fileKey(hostKey, path));

export const takeDiskVersion = (hostKey: string, path: string) =>
  takeTheirs(fileKey(hostKey, path));

/** The explorer's publisher: which files a Working agent is changing in this Workspace. */
export const setAgentFiles = (
  hostKey: string,
  workspaceId: string,
  files: ReadonlyMap<string, HarnessKind>
) =>
  editorStore.setState((s) => ({
    agentFiles: { ...s.agentFiles, [workspaceKey(hostKey, workspaceId)]: files },
  }));

let unpersist: (() => void) | null = null;

/** Sets up the Editor once per window: its files, drafts, prefs; restores the tabs. */
export const startEditor = (config: EditorConfig) => {
  configureEditor(config);
  const kv = config.kv;

  unpersist?.();
  unpersist = null;

  if (kv !== null) editorStore.setState({ tabs: readTabs(kv) });

  for (const request of early.splice(0)) openFile(request);

  if (kv === null) return;
  editorStore.setState({ tabs: readTabs(kv) });
  let timer: ReturnType<typeof setTimeout> | null = null;

  unpersist = editorStore.subscribe((state, prev) => {
    if (state.tabs === prev.tabs) return;

    if (timer !== null) clearTimeout(timer);
    timer = setTimeout(() => writeTabs(kv, editorStore.getState().tabs), 300);
  });
};

/**
 * Copy for Streamdown's code blocks, Mermaid sources and tables, as the shared
 * CopyButton (DESIGN.md, Copy button). Streamdown's own copy controls write
 * with the browser clipboard API, which the Desktop App's renderer may not use.
 */
import { CopyButton } from "@polaris/ui";
import { type ComponentProps, useRef } from "react";
import {
  type Components,
  defaultComponents,
  type ExtraProps,
  extractTableDataFromElement,
  tableDataToMarkdown,
} from "streamdown";

type Hast = NonNullable<ExtraProps["node"]>;

/** The text under a hast node, as the fence holds it. */
const textOf = (node: Hast | Hast["children"][number] | undefined): string => {
  if (node === undefined) return "";

  if (node.type === "text") return node.value;

  return "children" in node ? node.children.map(textOf).join("") : "";
};

const Code = defaultComponents.code;

const Table = defaultComponents.table;

const CORNER = "absolute top-0.5 right-1 z-10";

/** Fenced code and Mermaid sources; pair with `copy: false` in Streamdown's code controls. */
export const COPY_CODE: Components = {
  // Only fenced code carries `data-block`; inline code stays as Streamdown draws it.
  code: (props) =>
    "data-block" in props ? (
      <div className="relative" data-copy="code">
        <Code {...props} />
        <CopyButton
          variant="icon"
          label="Copy code"
          text={() => textOf(props.node).replace(/\n$/, "")}
          className={CORNER}
        />
      </div>
    ) : (
      <Code {...props} />
    ),
};

/** Tables, as Markdown; pair with `copy: false` in Streamdown's table controls. */
export const COPY_TABLE: Components = { table: (props) => <CopyTable {...props} /> };

/** A table copies as Markdown, read from what is rendered. */
const CopyTable = (props: ComponentProps<typeof Table>) => {
  const root = useRef<HTMLDivElement>(null);

  const markdown = () => {
    const table = root.current?.querySelector("table");

    return table == null ? "" : tableDataToMarkdown(extractTableDataFromElement(table));
  };

  return (
    <div ref={root} className="relative" data-copy="table">
      {/* Tables have no header row of their own: the button gets a strip above, never over a cell. */}
      <div className="flex h-7 justify-end">
        <CopyButton variant="icon" label="Copy table" text={markdown} />
      </div>
      <Table {...props} />
      <CopyButton variant="icon" label="Copy table" text={markdown} className={CORNER} />
    </div>
  );
};

/**
 * The status bar's tab completion item and its card (DESIGN.md, Tab completion status card):
 * the star and a short label; hover or focus opens the card after 300ms, click or ↵ at once
 * with focus on its first action, as the Session context card does.
 */
import { HoverCard, HoverCardContent, HoverCardTrigger, PixelPolarisIcon } from "@polaris/ui";
import { type FocusEvent, useEffect, useId, useRef, useState } from "react";
import { hostInSentence } from "../../../shell/hostCopy.ts";
import { useApp, useCommands } from "../../../shell/hooks.ts";
import { polaris } from "../../bridge.ts";
import { DEFAULT_PREDICTION_PREFERENCES } from "../../../../shared/predictionPlacement.ts";
import { inSentence } from "../../settings/editor/placementRows.ts";
import { fileKey } from "../model/drafts.ts";
import { useTrustStatus } from "../trust/store.ts";
import { runCardAction } from "./card/actions.ts";
import { CompletionCard, type Outcome } from "./card/CompletionCard.tsx";
import { useMemoryLine, useServerReport } from "./card/hooks.ts";
import { gb } from "./card/managed.ts";
import { completionCard, type CardAction, type CardActionId } from "./card/model.ts";
import { setHostPreferences, usePrediction, watchManaged } from "./store.ts";
import { clientCopy } from "../../../../shared/clientCopy.ts";

const message = (cause: unknown) => (cause instanceof Error ? cause.message : String(cause));

export interface PredictionStatusProps {
  readonly hostKey: string;
  /** The open file, for its Workspace's trust. */
  readonly path?: string | undefined;
}

export const PredictionStatus = ({ hostKey, path }: PredictionStatusProps) => {
  const host = useApp((state) => state.hosts.find((item) => item.key === hostKey));
  const state = usePrediction((value) => value);
  const trust = useTrustStatus(path === undefined ? "" : fileKey(hostKey, path));
  const commands = useCommands();
  const api = polaris();
  const titleId = useId();
  const content = useRef<HTMLDivElement>(null);
  const acknowledged = useRef(false);
  const [open, setOpen] = useState(false);
  // Click or ↵ opens it at once and moves focus in; hover leaves focus in the editor.
  const [focusIn, setFocusIn] = useState(false);
  const [running, setRunning] = useState<{ readonly id: CardActionId } | null>(null);
  const [outcome, setOutcome] = useState<Outcome | null>(null);
  const [revision, setRevision] = useState(0);
  const inspection = state.inspections[hostKey];

  const offer =
    host?.status.state === "connected" && !state.configured && inspection?.offer === true;

  useEffect(() => {
    if (!offer || acknowledged.current) return;
    acknowledged.current = true;
    void api.request("prediction.discoveryShown", {});
  }, [api, offer]);

  // The portal mounts the content a frame after `open`, so focus waits for it.
  useEffect(() => {
    if (!open || !focusIn) return;

    const frame = requestAnimationFrame(() =>
      content.current?.querySelector<HTMLElement>("[role=menuitem]")?.focus()
    );

    return () => cancelAnimationFrame(frame);
  }, [open, focusIn]);

  const clientName = inSentence(inspection?.clientLabel ?? clientCopy().localHost);

  const input = {
    connection: host?.status.state,
    hostName: hostInSentence(host),
    hostKey,
    enabled: state.enabled,
    offer,
    preferences: state.preferences[hostKey] ?? DEFAULT_PREDICTION_PREFERENCES,
    inspection,
    result: state.enabled ? state.results[hostKey] : undefined,
    failure: state.failures[hostKey],
    trusted: trust === null ? null : trust.trust.trusted,
  };

  const preview = completionCard({ ...input, server: null, memory: null });
  const target = preview.target;
  const managed = preview.managed;
  const managedSide = managed?.side;
  const busy = preview.kind === "downloading" || preview.kind === "loading";

  // The managed server pushes its phases (a download, a lazy start) while completion is on.
  useEffect(() => {
    if (managedSide === undefined || (!open && !state.enabled)) return;

    return watchManaged(api, hostKey, managedSide);
  }, [api, hostKey, managedSide, open, state.enabled]);

  const ownsTarget = managed !== null && managed.status.endpoint?.url === target?.endpoint.url;
  const server = useServerReport(api, hostKey, target, open && !ownsTarget, revision);
  const probed = useMemoryLine(api, open, target?.side === "client" && !ownsTarget, clientName);

  const memory =
    ownsTarget && managed.status.memoryBytes !== null
      ? `Polaris model server on ${target?.machine} · ${gb(managed.status.memoryBytes)} of memory, counted apart from Polaris`
      : probed;

  const view = completionCard({ ...input, server: server.report, memory });

  const run = (action: CardAction) => {
    setRunning({ id: action.id });
    setOutcome(null);
    void runCardAction(action, {
      api,
      hostKey,
      view,
      remember: server.remember,
      openSettings: () => {
        setOpen(false);
        commands.runAny("settings.editor");
      },
    })
      .then((text) => {
        if (action.id === "check-again") setRevision((n) => n + 1);
        setOutcome(text === null ? null : { text, failed: false });
      })
      .catch((cause: unknown) => setOutcome({ text: message(cause), failed: true }))
      .finally(() => setRunning(null));
  };

  const chooseModel = (model: string | null) => {
    setOutcome(null);
    void setHostPreferences(api, hostKey, { model, format: null }).catch((cause: unknown) =>
      setOutcome({ text: message(cause), failed: true })
    );
  };

  // Focus moving into the card isn't leaving it; Radix closes a hover card on the trigger's blur.
  const within = (event: FocusEvent) =>
    event.relatedTarget instanceof Node && content.current?.contains(event.relatedTarget) === true;

  return (
    <HoverCard
      open={open}
      onOpenChange={(next) => {
        if (!next) setFocusIn(false);
        setOpen(next);
      }}
    >
      <HoverCardTrigger asChild>
        <button
          type="button"
          data-testid="prediction-status"
          data-kind={view.kind}
          aria-label={`Tab completion: ${view.title}`}
          aria-expanded={open}
          onBlur={(event) => {
            if (within(event)) event.preventDefault();
          }}
          onClick={() => {
            setFocusIn(true);
            setOpen(true);
          }}
          className="text-caption text-text-subtle hover:text-text-default focus-visible:outline-starlight flex min-w-0 cursor-default items-center gap-1.5 truncate rounded-sm focus-visible:outline-2"
        >
          <PixelPolarisIcon
            aria-hidden
            size={12}
            className={view.kind === "serving" ? "shrink-0" : "shrink-0 opacity-50"}
          />
          <span className="truncate">{view.label}</span>
        </button>
      </HoverCardTrigger>
      <HoverCardContent
        side="top"
        align="end"
        ref={content}
        tabIndex={-1}
        role="dialog"
        aria-labelledby={titleId}
        data-testid="completion-card"
        data-kind={view.kind}
        onBlur={(event) => {
          if (!within(event) && running === null) setOpen(false);
        }}
        className="rounded-row flex w-[360px] flex-col overflow-hidden p-0 outline-none"
      >
        <CompletionCard
          view={view}
          running={running}
          outcome={outcome}
          titleId={titleId}
          onRun={run}
          onModel={chooseModel}
        />
      </HoverCardContent>
    </HoverCard>
  );
};

/**
 * One Risk Summary: started (or the cached one answered), then the Rules and
 * the Reviewer in turn, the cost line, and its end. The Reviewer's layer runs
 * in its own read-only Agent Session and reports through `output.ts`.
 */
import {
  DomainEvent,
  LayerRun,
  type ResolvedReviewer,
  type ReviewContext,
  type ReviewCheckoutId,
  type ReviewerChoice,
  type ReviewerSettings,
  ReviewerRun,
  type ReviewSubject,
  RiskSummary,
  RiskSummaryId,
  RiskSummaryLayers,
  RiskSummaryRef,
  type SessionId,
  type WorkspaceId,
} from "@polaris/protocol";
import { Effect, Result } from "effect";
import { checkoutGitRaw } from "../git/review/refs.ts";
import { recordRulesLayer } from "../rules/index.ts";
import { EventStore } from "../store/EventStore.ts";
import { currentPlanLimitNote, reviewerCost } from "./cost.ts";
import { type ChangeDiff, readDiff } from "./diff.ts";
import { isIgnored, readInstructions } from "./instructions.ts";
import {
  parseReviewerReply,
  type ReadLines,
  type ReviewerOutput,
  toRiskFindings,
} from "./output.ts";
import { repairPrompt, reviewPrompt } from "./prompt.ts";
import { canRunChecks } from "./policy.ts";
import { type ReviewRange, resolveRange } from "./range.ts";
import { askFirst, changedLines, switchedOff } from "./when.ts";
import { continueReviewerSession, startReviewerSession, type TurnOutcome } from "./session.ts";

export interface RunRequest {
  readonly workspaceId: WorkspaceId;
  readonly subject: ReviewSubject;
  readonly checkoutId: ReviewCheckoutId | null;
  readonly since: string | null;
  readonly refresh: boolean;
  readonly context: ReviewContext | null;
  /** The Rules alone, as after each Agent Session Turn; skipped when the Turn changed nothing. */
  readonly rulesOnly?: boolean;
}

const commit = (events: ReadonlyArray<DomainEvent>) =>
  Effect.gen(function* () {
    const store = yield* EventStore;
    yield* store.commit({ commandId: null, decide: () => Effect.succeed(events) });
  }).pipe(Effect.orDie);

const agentLayer = (summaryId: RiskSummaryId, run: LayerRun) =>
  commit([DomainEvent.cases.RiskSummaryLayerChanged.make({ summaryId, layer: "agent", run })]);

const readSummary = (summaryId: RiskSummaryId) =>
  Effect.gen(function* () {
    const store = yield* EventStore;

    return yield* store.review.riskSummary(RiskSummaryRef.cases.ById.make({ summaryId }));
  });

const decoder = new TextDecoder();

/** A file's lines at head (`new`) or the diff's base (`old`), read from git's objects. */
export const linesAt =
  (cwd: string, base: string, head: string): ReadLines =>
  (path, side) =>
    Effect.promise(async () => {
      const result = await checkoutGitRaw(cwd, ["show", `${side === "new" ? head : base}:${path}`]);

      return result.code === 0 ? decoder.decode(result.stdout).split("\n") : null;
    });

/** True when `base` and `head` hold the same files (a Turn that changed nothing). */
const sameTree = (range: ReviewRange) =>
  Effect.promise(async () => {
    const result = await checkoutGitRaw(range.cwd, ["diff", "--quiet", range.base, range.head]);

    return result.code === 0;
  });

// ── Starting ────────────────────────────────────────────────────────────────

/** The summary to answer: the cached one for the key (unless refreshed or failed), else null. */
/**
 * The summary to answer: the cached one for the key, unless refreshed or
 * failed, or it skipped the Reviewer and this run would not (Rules after a
 * Turn, then the session opened in Review; a switch turned back on).
 */
const cached = (range: ReviewRange, refresh: boolean, plan: ReviewerPlan) =>
  Effect.gen(function* () {
    if (refresh) return null;
    const store = yield* EventStore;

    const summary = yield* store.review.riskSummary(
      RiskSummaryRef.cases.ByKey.make({ key: range.key })
    );

    if (summary === null || summary.status === "failed") return null;
    const runsReviewer = plan.resolved.choice !== null && plan.off === null;

    return summary.layers.agent.status === "skipped" && runsReviewer ? null : summary;
  });

/** The agent layer's note on the Rules run after each Agent Session Turn. */
export const RULES_AFTER_TURN =
  "Rules after this Turn. The Reviewer runs when you open the session in Review or accept its Turns.";

/** Who reviews this summary, and whether "When it runs" lets them now. */
export interface ReviewerPlan {
  readonly resolved: ResolvedReviewer;
  /** Why the Reviewer doesn't run by itself here (a switch is off); null when it does. */
  readonly off: string | null;
  /** Ask first above this many changed lines; null never asks. */
  readonly askAboveLines: number | null;
}

const agentAtStart = ({ resolved, off }: ReviewerPlan) => {
  if (resolved.choice === null) return LayerRun.make({ status: "skipped", note: resolved.note });

  return off === null
    ? LayerRun.make({ status: "pending", note: null })
    : LayerRun.make({ status: "skipped", note: off });
};

const startedSummary = (
  request: RunRequest,
  range: ReviewRange,
  plan: ReviewerPlan,
  now: string
) => {
  const { resolved } = plan;

  return RiskSummary.make({
    id: RiskSummaryId.make(`rs_${crypto.randomUUID()}`),
    key: range.key,
    workspaceId: range.workspaceId,
    subject: request.subject,
    checkoutId: range.checkoutId,
    status: "running",
    layers: RiskSummaryLayers.make({
      rules: LayerRun.make({ status: "pending", note: null }),
      agent: agentAtStart(plan),
    }),
    reviewer:
      resolved.choice === null
        ? null
        : ReviewerRun.make({
            harness: resolved.choice.harness,
            model: resolved.choice.model,
            effort: resolved.choice.effort,
            sessionId: null,
          }),
    cost: null,
    note: [range.note, resolved.note].filter((n) => n !== null).join(" ") || null,
    findings: [],
    startedAt: now,
    endedAt: null,
  });
};

// ── The Reviewer's layer ────────────────────────────────────────────────────

interface AgentInput {
  readonly summary: RiskSummary;
  readonly range: ReviewRange;
  readonly choice: ReviewerChoice;
  readonly context: ReviewContext | null;
}

const withoutIgnored = (diff: ChangeDiff, ignore: ReadonlyArray<string>): ChangeDiff =>
  ignore.length === 0 ? diff : { files: diff.files.filter((f) => !isIgnored(ignore, f.path)) };

const whyOf = (range: ReviewRange, context: ReviewContext | null): string | null => {
  if (context !== null) return context.body.trim() === "" ? null : context.body;

  return range.prompts.length === 0
    ? null
    : range.prompts.map((prompt, i) => `Prompt ${i + 1}:\n${prompt}`).join("\n\n");
};

/** The previous summary's open Reviewer Findings and session, for "only the new changes". */
const previousRun = (range: ReviewRange) =>
  Effect.gen(function* () {
    if (range.previousKey === null) return { findings: [], sessionId: null };
    const store = yield* EventStore;

    const previous = yield* store.review.riskSummary(
      RiskSummaryRef.cases.ByKey.make({ key: range.previousKey })
    );

    return {
      findings: (previous?.findings ?? []).filter(
        (f) => f.source === "agent" && f.status === "open"
      ),
      sessionId: previous?.reviewer?.sessionId ?? null,
    };
  });

/** The reply decoded, after one repair Turn if it didn't decode. */
const decodeWithRepair = (sessionId: SessionId, outcome: TurnOutcome) =>
  Effect.gen(function* () {
    const first = parseReviewerReply(outcome.reply ?? "");

    if (Result.isSuccess(first)) return first;
    const repaired = yield* continueReviewerSession(sessionId, repairPrompt(first.failure));

    return parseReviewerReply(repaired.reply ?? "");
  });

interface AgentResult {
  readonly sessionId: SessionId;
  readonly output: ReviewerOutput | null;
  readonly note: string | null;
}

const askReviewer = Effect.fn("askReviewer")(function* (input: AgentInput) {
  const { range, choice, summary } = input;
  const diff = yield* Effect.promise(() => readDiff(range.cwd, range.base, range.head));

  const instructions = yield* Effect.promise(() =>
    readInstructions({ cwd: range.cwd, head: range.head, repo: range.key.repo })
  );

  const current = yield* readSummary(summary.id);
  const previous = yield* previousRun(range);

  const prompt = reviewPrompt({
    subject: input.context === null ? range.title : `${range.title}: ${input.context.title}`,
    why: whyOf(range, input.context),
    instructions: instructions.text,
    ruleFindings: (current?.findings ?? []).filter((f) => f.source === "rule"),
    diff: withoutIgnored(diff, instructions.ignore),
    base: range.base,
    head: range.head,
    since: range.key.since,
    earlierFindings: previous.findings,
    runChecks: canRunChecks(choice.harness),
  });

  const outcome =
    previous.sessionId === null
      ? yield* startReviewerSession({
          workspaceId: range.workspaceId,
          checkoutId: range.checkoutId,
          choice,
          title: `Reviewer · ${range.title}`,
          prompt,
        })
      : {
          sessionId: previous.sessionId,
          ...(yield* continueReviewerSession(previous.sessionId, prompt)),
        };

  if (outcome.reply === null) {
    return {
      sessionId: outcome.sessionId,
      output: null,
      note: `The Reviewer's Turn ${outcome.status === "interrupted" ? "was interrupted" : "failed"}.`,
    } satisfies AgentResult;
  }

  const decoded = yield* decodeWithRepair(outcome.sessionId, outcome);

  return {
    sessionId: outcome.sessionId,
    output: Result.isSuccess(decoded) ? decoded.success : null,
    note: Result.isSuccess(decoded)
      ? null
      : "The Reviewer's reply couldn't be read, even after asking again.",
  } satisfies AgentResult;
});

/** Runs the Reviewer and records its Findings; the session it ran in, if any. */
const runAgentLayer = (input: AgentInput) =>
  Effect.gen(function* () {
    const { summary, range } = input;
    yield* agentLayer(summary.id, LayerRun.make({ status: "running", note: null }));

    const result = yield* askReviewer(input).pipe(
      Effect.catchCause((cause) => Effect.as(Effect.logWarning("the Reviewer failed", cause), null))
    );

    if (result === null || result.output === null) {
      yield* agentLayer(
        summary.id,
        LayerRun.make({
          status: "failed",
          note: result?.note ?? "The Reviewer could not run.",
        })
      );

      return result?.sessionId ?? null;
    }

    const converted = yield* toRiskFindings(
      result.output.findings,
      yield* Effect.promise(() => readDiff(range.cwd, range.base, range.head)),
      linesAt(range.cwd, range.base, range.head)
    );

    const dropped =
      converted.dropped > 0
        ? `${converted.dropped} of the Reviewer's findings pointed outside the diff and were left out.`
        : null;

    yield* commit([
      ...(converted.findings.length > 0
        ? [
            DomainEvent.cases.RiskFindingsRecorded.make({
              summaryId: summary.id,
              findings: converted.findings,
            }),
          ]
        : []),
      DomainEvent.cases.RiskSummaryLayerChanged.make({
        summaryId: summary.id,
        layer: "agent",
        run: LayerRun.make({ status: "completed", note: dropped }),
      }),
    ]);

    return result.sessionId;
  });

// ── The whole run ───────────────────────────────────────────────────────────

const ended = (summary: RiskSummary, sessionId: SessionId | null, resolved: ResolvedReviewer) =>
  Effect.gen(function* () {
    const choice = resolved.choice;
    const after = yield* readSummary(summary.id);
    const rulesFailed = after?.layers.rules.status === "failed";
    const agentFailed = after?.layers.agent.status !== "completed";

    const cost =
      choice === null || sessionId === null
        ? null
        : yield* reviewerCost(choice.harness, sessionId, summary.startedAt).pipe(
            Effect.catchCause(() => Effect.succeed(null))
          );

    const limitNote = choice === null ? null : yield* currentPlanLimitNote(choice.harness);
    const note = [summary.note, limitNote].filter((n) => n !== null).join(" ") || null;

    yield* commit([
      DomainEvent.cases.RiskSummaryEnded.make({
        summaryId: summary.id,
        status: rulesFailed && agentFailed ? "failed" : "completed",
        reviewer:
          choice === null
            ? null
            : ReviewerRun.make({
                harness: choice.harness,
                model: choice.model,
                effort: choice.effort,
                sessionId,
              }),
        cost,
        note,
      }),
    ]);

    return !(rulesFailed && agentFailed);
  });

/** The layers of a started summary, then its end. Never fails: a broken layer is recorded. */
/** The "Ask first" note when the change is over the threshold, else null. */
const overThreshold = (range: ReviewRange, askAboveLines: number | null) =>
  askAboveLines === null
    ? Effect.succeed(null)
    : Effect.promise(() => readDiff(range.cwd, range.base, range.head)).pipe(
        Effect.map((diff) => askFirst(changedLines(diff), askAboveLines))
      );

export const runLayers = (
  summary: RiskSummary,
  range: ReviewRange,
  input: {
    readonly plan: ReviewerPlan;
    readonly context: ReviewContext | null;
  }
) =>
  Effect.gen(function* () {
    yield* recordRulesLayer(summary.id, {
      cwd: range.cwd,
      base: range.base,
      head: range.head,
      mode: range.mode,
    }).pipe(Effect.catchCause((cause) => Effect.logWarning("the Rules failed", cause)));

    const { plan } = input;
    const choice = plan.off === null ? plan.resolved.choice : null;
    const waiting = choice === null ? null : yield* overThreshold(range, plan.askAboveLines);

    if (waiting !== null)
      yield* agentLayer(summary.id, LayerRun.make({ status: "pending", note: waiting }));

    const sessionId =
      choice === null || waiting !== null
        ? null
        : yield* runAgentLayer({ summary, range, choice, context: input.context });

    return yield* ended(summary, sessionId, plan.resolved);
  });

export const startRun = (
  request: RunRequest,
  resolve: (
    workspaceId: WorkspaceId
  ) => Effect.Effect<{ readonly resolved: ResolvedReviewer; readonly settings: ReviewerSettings }>
) =>
  Effect.gen(function* () {
    const range = yield* resolveRange(request.subject, request.checkoutId, request.since);
    const existing = yield* cached(range, request.refresh);

    if (request.rulesOnly === true && (yield* sameTree(range))) {
      return { summary: null, range, plan: null };
    }

    const { resolved, settings } = yield* resolve(range.workspaceId);

    const plan: ReviewerPlan = {
      resolved,
      off:
        request.rulesOnly === true
          ? RULES_AFTER_TURN
          : switchedOff(request.subject, settings, request.refresh),
      askAboveLines: request.refresh ? null : settings.askAboveLines,
    };

    const existing = yield* cached(range, request.refresh, plan);

    if (existing !== null) return { summary: existing, range, plan: null };

    const summary = startedSummary(request, range, plan, new Date().toISOString());
    yield* commit([DomainEvent.cases.RiskSummaryStarted.make({ summary })]);

    return { summary, range, plan };
  });

history.after:
/** True when `base` and `head` hold the same files (a Turn that changed nothing). */
const sameTree = (range: ReviewRange) =>
  Effect.promise(async () => {
    const result = await checkoutGitRaw(range.cwd, ["diff", "--quiet", range.base, range.head]);

    return result.code === 0;
  });

if (summary === null || summary.status === "failed") return null;
const runsReviewer = plan.resolved.choice !== null && plan.off === null;

return summary.layers.agent.status === "skipped" && runsReviewer ? null : summary;

/** The agent layer's note on the Rules run after each Agent Session Turn. */
export const RULES_AFTER_TURN =
  "Rules after this Turn. The Reviewer runs when you open the session in Review or accept its Turns.";

if (request.rulesOnly === true && (yield* sameTree(range))) {
  return { summary: null, range, plan: null };
}

