/**
 * Open in editor: the one action every `path:line` in the app runs (transcripts, Claims,
 * Overview, findings, Changes, Review), and ⌘P's pick. It selects the Workspace holding the
 * file, switches to Edit, and leaves an open request the editor pane takes with
 * `useEditorOpenRequest()`. Each request has its own `seq`, so the same place can be asked again.
 */
import type { Workspace, WorkspaceId, Worktree } from "@polaris/protocol";
import { useStore } from "zustand";
import { createStore } from "zustand/vanilla";
import type { AppState } from "../store/store.ts";
import type { ShellActions } from "./navigation.ts";

export interface EditorLocation {
  readonly hostKey: string;
  /** Absolute on the Host, or relative to `root`. */
  readonly path: string;
  /** What a relative `path` is relative to: a session's cwd, a checkout, a Workspace. */
  readonly root?: string | null;
  /** The Workspace to open it in; found from the path when omitted. */
  readonly workspaceId?: WorkspaceId | null;
  /** 1-based. */
  readonly line?: number | null;
  /** 1-based. */
  readonly column?: number | null;
  /** A folder to show in the explorer (a Review Checkout's root), not a file to open. */
  readonly folder?: boolean;
}

export interface EditorOpenRequest {
  readonly seq: number;
  readonly hostKey: string;
  readonly workspaceId: WorkspaceId;
  /** Absolute on the Host. */
  readonly path: string;
  readonly line: number | null;
  readonly column: number | null;
  readonly folder: boolean;
}

interface EditorRoute {
  readonly request: EditorOpenRequest | null;
}

export const editorRoute = createStore<EditorRoute>(() => ({ request: null }));

let seq = 0;

/** The latest open request; the editor pane opens or focuses its tab and reveals the line. */
export const useEditorOpenRequest = (): EditorOpenRequest | null =>
  useStore(editorRoute, (s) => s.request);

const trimSlash = (path: string) => (path.length > 1 ? path.replace(/\/+$/, "") : path);

/** `path` made absolute against `root`, with `.` and `..` segments folded. */
export const resolvePath = (path: string, root: string | null | undefined): string => {
  const joined = path.startsWith("/") || !root ? path : `${trimSlash(root)}/${path}`;
  const parts: Array<string> = [];

  for (const part of joined.split("/")) {
    if (part === "" || part === ".") continue;

    if (part === "..") parts.pop();
    else parts.push(part);
  }

  return joined.startsWith("/") ? `/${parts.join("/")}` : parts.join("/");
};

const contains = (root: string, path: string) => {
  const base = trimSlash(root);

  return path === base || path.startsWith(base === "/" ? "/" : `${base}/`);
};

export interface HostPlaces {
  readonly workspaces: ReadonlyMap<string, Workspace>;
  readonly worktrees: ReadonlyMap<string, Worktree>;
}

/** The Workspace whose folder, or one of whose Worktrees, holds `path` most closely. */
export const workspaceFor = (places: HostPlaces, path: string): WorkspaceId | null => {
  const roots = [
    ...[...places.workspaces.values()].map((w) => ({ id: w.id, root: w.path })),
    ...[...places.worktrees.values()].map((w) => ({ id: w.workspaceId, root: w.path })),
  ];

  let best: WorkspaceId | null = null;
  let length = -1;

  for (const { id, root } of roots) {
    if (contains(root, path) && root.length > length) {
      best = id;
      length = root.length;
    }
  }

  return best;
};

const positive = (n: number | null | undefined) =>
  n === null || n === undefined || !Number.isFinite(n) || n < 1 ? null : Math.floor(n);

/** The request for `location`, or null when no Workspace on its Host holds the file. */
export const editorRequest = (
  app: Pick<AppState, "hostModels">,
  location: EditorLocation
): Omit<EditorOpenRequest, "seq"> | null => {
  const path = resolvePath(location.path, location.root);
  const model = app.hostModels[location.hostKey];

  const workspaceId =
    location.workspaceId ?? (model === undefined ? null : workspaceFor(model, path));

  if (workspaceId === null || !path.startsWith("/")) return null;

  return {
    hostKey: location.hostKey,
    workspaceId,
    path,
    line: positive(location.line),
    column: positive(location.column),
    folder: location.folder ?? false,
  };
};

export type OpenInEditorActions = Pick<ShellActions, "selectWorkspace" | "setMode">;

export interface OpenInEditorContext {
  readonly app: Pick<AppState, "hostModels">;
  readonly actions: OpenInEditorActions;
  /** The Workspace selected now; switching to it again would drop the selected session. */
  readonly selected: { readonly hostKey: string | null; readonly workspaceId: string | null };
}

/** Opens `location` in Edit; false when it isn't inside any Workspace on its Host. */
export const openInEditor = (context: OpenInEditorContext, location: EditorLocation): boolean => {
  const request = editorRequest(context.app, location);

  if (request === null) return false;

  const { hostKey, workspaceId } = request;

  if (context.selected.hostKey !== hostKey || context.selected.workspaceId !== workspaceId)
    context.actions.selectWorkspace({ hostKey, workspaceId });

  context.actions.setMode("edit");
  seq += 1;
  editorRoute.setState({ request: { ...request, seq } });
  context.actions.setMode("edit");

  return true;
};

/** `path:line` or `path:line:column` as written in transcripts and tool output. */
export interface ParsedLocation {
  readonly path: string;
  readonly line: number | null;
  readonly column: number | null;
}

export const parseLocation = (text: string): ParsedLocation => {
  const match = /^(.*?):(\d+)(?::(\d+))?$/.exec(text.trim());

  if (match === null) return { path: text.trim(), line: null, column: null };

  return {
    path: match[1] ?? "",
    line: Number(match[2]),
    column: match[3] === undefined ? null : Number(match[3]),
  };
};

/**
 * The Harness drivers this Daemon runs. The Codex driver owns the Host's shared
 * `codex app-server`, which lives as long as this layer's scope.
 *
 * Each driver's module is loaded on first use (`probe`, `open`), not at start:
 * the Claude Agent SDK and the Codex protocol schemas would otherwise sit in
 * every idle Daemon's memory. `kind` and `capabilities` are known up front
 * (the engine reads them without opening anything), and Claude's terminal
 * follow-along comes from the hook receiver, which does not need the SDK.
 *
 * Under launchd / systemd a user's PATH often lacks nvm or Homebrew bins, so
 * `POLARIS_CODEX` and `POLARIS_CLAUDE` can point at the binaries explicitly.
 */
import type { HarnessKind, KnownHarnessKind } from "@polaris/protocol";
import { Effect, Layer, Scope } from "effect";
import { HarnessRegistry, ServiceError } from "../services.ts";
import { ClaudeHookReceiver } from "./claude/hooks.ts";
import { type HarnessDriver, HarnessError } from "./HarnessDriver.ts";

const binary = (env: string, name: string): string | null =>
  process.env[env] || Bun.which(name) || null;

/** What each driver declares; checked against the loaded drivers in registry.test.ts. */
export const DRIVER_CAPABILITIES = {
  codex: { steer: true, liveCoAttach: true, switchModel: true },
  claude: { steer: true, liveCoAttach: false, switchModel: true },
  bench: { steer: true, liveCoAttach: true, switchModel: true },
} as const satisfies Record<KnownHarnessKind | "bench", HarnessDriver["capabilities"]>;

/**
 * A driver that loads the real one the first time it is probed or opened.
 * `extra` carries members that must not wait for the load (Claude's follow-along).
 */
export const lazyDriver = (
  kind: HarnessKind,
  capabilities: HarnessDriver["capabilities"],
  load: Effect.Effect<HarnessDriver>,
  extra: Pick<HarnessDriver, "terminalFollow"> = {}
): Effect.Effect<HarnessDriver> =>
  Effect.map(Effect.cached(load), (loaded) => ({
    kind,
    capabilities,
    ...extra,
    probe: Effect.flatMap(loaded, (driver) => driver.probe),
    listModels: Effect.flatMap(
      loaded,
      (driver) =>
        driver.listModels ??
        Effect.fail(new HarnessError({ harness: kind, message: "it doesn't list its Models yet" }))
    ),
    open: (options) => Effect.flatMap(loaded, (driver) => driver.open(options)),
  }));

export const HarnessRegistryLive = Layer.effect(
  HarnessRegistry,
  Effect.gen(function* () {
    const hookReceiver = yield* ClaudeHookReceiver;
    // The app-server the Codex driver may start belongs to this layer, not to the first `open`.
    const scope = yield* Effect.scope;
    const codexPath = binary("POLARIS_CODEX", "codex");
    const claudePath = binary("POLARIS_CLAUDE", "claude");
    // Benchmarks only (packages/bench): a scripted Harness stands in for every kind.
    const bench = process.env.POLARIS_BENCH_HARNESS === "1";

    const benchDriver = (kind: HarnessKind) =>
      lazyDriver(
        kind,
        DRIVER_CAPABILITIES.bench,
        Effect.promise(() => import("./bench/BenchDriver.ts")).pipe(
          Effect.map(({ makeBenchDriver }) => makeBenchDriver(kind))
        )
      );

    const drivers: ReadonlyArray<HarnessDriver> = bench
      ? [yield* benchDriver("codex"), yield* benchDriver("claude")]
      : [
          yield* lazyDriver(
            "codex",
            DRIVER_CAPABILITIES.codex,
            Effect.promise(() => import("./codex/CodexDriver.ts")).pipe(
              Effect.flatMap(({ makeCodexDriver }) => makeCodexDriver({ codexPath })),
              Scope.provide(scope)
            )
          ),
          yield* lazyDriver(
            "claude",
            DRIVER_CAPABILITIES.claude,
            Effect.promise(() => import("./claude/ClaudeDriver.ts")).pipe(
              Effect.map(({ makeClaudeDriver }) =>
                // Looked up per session, so a Claude Code installed after start is found.
                makeClaudeDriver({
                  hookReceiver,
                  claudePath: () => binary("POLARIS_CLAUDE", "claude"),
                })
              )
            ),
            // While In Terminal, Polaris follows the TUI through its HTTP hooks (hooks.ts).
            { terminalFollow: { events: hookReceiver.events, release: hookReceiver.release } }
          ),
        ];

    const byKind = new Map<HarnessKind, HarnessDriver>(drivers.map((d) => [d.kind, d]));

    return HarnessRegistry.of({
      get: (kind) => {
        const driver = byKind.get(kind);

        return driver
          ? Effect.succeed(driver)
          : Effect.fail(new ServiceError({ service: "harness", message: `no ${kind} driver` }));
      },
      all: Effect.succeed(drivers),
    });
  })
).pipe(Layer.provide(ClaudeHookReceiver.layer));

history.after:
// Looked up per session, so a Claude Code installed after start is found.
makeClaudeDriver({
  hookReceiver,
  claudePath: () => binary("POLARIS_CLAUDE", "claude"),
})

