/**
 * What the tab knows about each worker beyond the graph: its session (Harness, Model, Host),
 * liveness from session events (never the model), and attention signals.
 */
import type { HarnessKind, ToolCallReference } from "@polaris/protocol";
import type { Plain } from "../../../store/plain.ts";
import type { SetupFact } from "./setup.ts";
import type { AttemptData } from "./types.ts";

/** What a worker is doing right now, from its session's items. */
export type Activity =
  | { readonly kind: "command"; readonly text: string; readonly since: string }
  | { readonly kind: "tool"; readonly text: string; readonly since: string }
  /** Queued for a worker slot on its Host (`__workers`, over the Host's cap). */
  | { readonly kind: "slot"; readonly host: string | null; readonly since: string }
  | {
      readonly kind: "lease";
      readonly resource: string;
      /** The Task holding it, when one does. */
      readonly holder: string | null;
      readonly since: string;
    };

export interface WorkerFacts {
  readonly harness: HarnessKind | null;
  /** The Model as the Harness names it, lowercase ("gpt-6.1-sol"). */
  readonly model: string | null;
  /** The worker's Host label when it isn't the Lead's Host. */
  readonly remoteHost: string | null;
  /** The worker's Host is Reconnecting or Offline (stale). */
  readonly hostAway: "reconnecting" | "offline" | null;
  readonly activity: Activity | null;
  readonly contextPercent: number | null;
  readonly queued: number;
  /** When the worker last produced output, shown while nothing runs. */
  readonly quietSince: string | null;
  /** Since when an approval has waited on the user, if one does. */
  readonly approvalSince: string | null;
  /** The worker ended without a Claim after its one nudge. */
  readonly stoppedWithoutClaiming: boolean;
  /** Whether the worker's session ha
  /** Subagents still working in the worker's session (rail nodes under its Attempt). */
  readonly subagents: ReadonlyArray<SubagentFact>;
}

export interface SubagentFact {
  readonly id: string;
  readonly title: string;
  /** The kind of helper as the Harness names it ("Explore"), when known. */
  readonly agent: string | null;
  readonly since: string;
}

export const NO_FACTS: WorkerFacts = {
  harness: null,
  model: null,
  remoteHost: null,
  hostAway: null,
  activity: null,
  contextPercent: null,
  queued: 0,
  quietSince: null,
  approvalSince: null,
  stoppedWithoutClaiming: false,
  activeTurn: null,
  subagents: [],
};

/** A verified receipt's tool call, resolved from the session that ran it. */
export interface ReceiptResult {
  readonly command: string;
  readonly exitCode: number | null;
}

export interface Facts {
  readonly now: number;
  readonly worker: (attempt: AttemptData) => WorkerFacts;
  readonly receipt: (ref: Plain<ToolCallReference>) => ReceiptResult | null;
  /** The Task's latest worktree setup run, on whichever Host's worker Session ran it. */
  readonly setup: (taskId: string) => SetupFact | null;
  /** The Lead's own Harness and Model (Gate rows) and how full its context is. */
  readonly lead: {
    readonly harness: HarnessKind | null;
    readonly model: string | null;
    readonly contextPercent: number | null;
  };
}

export const plainFacts = (patch: Partial<Facts> = {}): Facts => ({
  now: Date.now(),
  worker: () => NO_FACTS,
  receipt: () => null,
  setup: () => null,
  lead: { harness: null, model: null, contextPercent: null },
  ...patch,
});

export const CONTEXT_WARN = 85;

/**
 * The tab strip (DESIGN.md, Editor: tabs; Paper E1): 36px tabs in `label`
 * type, the active one joined to the code, a dot for unsaved edits, a close
 * mark on the active tab, and a 12px dither while an agent changes the file.
 */
import { cn, CloseIcon, Dither } from "@polaris/ui";
import { type MouseEvent, useEffect, useRef } from "react";
import type { TabView } from "../runtime/hooks.ts";

export interface TabsProps {
  readonly tabs: ReadonlyArray<TabView>;
  readonly active: string | null;
  readonly onSelect: (path: string) => void;
  readonly onPin: (path: string) => void;
  readonly onClose: (path: string) => void;
}

/** The trailing 12px slot: the unsaved dot, swapped for the close mark on hover or when active. */
const TrailingSlot = ({
  tab,
  active,
  onClose,
}: {
  tab: TabView;
  active: boolean;
  onClose: () => void;
}) => {
  const close = (event: MouseEvent) => {
    event.stopPropagation();
    onClose();
  };

  return (
    <span className="relative flex size-3 shrink-0 items-center justify-center">
      {tab.dirty ? (
        <span
          aria-label="Unsaved"
          className="bg-text-subtle size-1.5 rounded-full group-hover/tab:invisible"
        />
      ) : null}
      <button
        type="button"
        tabIndex={-1}
        aria-label={`Close ${tab.label}`}
        onClick={close}
        className={cn(
          "absolute inset-0 flex items-center justify-center rounded-[3px] text-text-subtle hover:text-text-default",
          active && !tab.dirty ? "visible" : "invisible group-hover/tab:visible"
        )}
      >
        <CloseIcon size={12} />
      </button>
    </span>
  );
};

export const Tabs = ({ tabs, active, onSelect, onPin, onClose }: TabsProps) => {
  const strip = useRef<HTMLDivElement>(null);

  // The active tab stays in view however many are open.
  useEffect(() => {
    strip.current
      ?.querySelector<HTMLElement>('[role="tab"][aria-selected="true"]')
      ?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }, [active, tabs.length]);

  return (
    <div
      ref={strip}
      role="tablist"
      aria-label="Open files"
      className="border-hairline bg-surface-sunken flex h-[37px] shrink-0 [scrollbar-width:none] overflow-x-auto border-b"
    >
      {tabs.map((tab) => {
        const selected = tab.id === active;

        return (
          <div
            key={tab.id}
            role="tab"
            tabIndex={selected ? 0 : -1}
            aria-selected={selected}
            title={tab.path}
            data-testid="editor-tab"
            data-view={tab.view ?? "source"}
            data-dirty={tab.dirty ? "" : undefined}
            onMouseDown={(event) => {
              if (event.button === 1) onClose(tab.id);
            }}
            onClick={() => onSelect(tab.id)}
            onDoubleClick={() => {
              if (tab.view === undefined) onPin(tab.id);
            }}
            onKeyDown={(event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                onSelect(tab.id);
              }

              if (event.key === "Delete" || event.key === "Backspace") {
                event.preventDefault();
                onClose(tab.id);
              }

              if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) {
                event.preventDefault();
                const at = tabs.findIndex((t) => t.id === tab.id);

                let index =
                  (at + (event.key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length;

                if (event.key === "Home") index = 0;

                if (event.key === "End") index = tabs.length - 1;
                const next = tabs[index];

                if (next !== undefined) {
                  onSelect(next.id);
                  strip.current?.querySelectorAll<HTMLElement>('[role="tab"]')[index]?.focus();
                }
              }
            }}
            className={cn(
              "group/tab flex h-9 max-w-[240px] shrink-0 cursor-default focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-starlight items-center gap-2 border-r border-hairline pr-3 pl-3.5 text-label select-none",
              selected
                ? "-mb-px h-[37px] bg-bg text-text-strong"
                : "text-text-subtle hover:text-text-default"
            )}
          >
            {tab.agent === null ? null : <Dither hue={tab.agent} size={12} moving />}
            <span className={cn("truncate", tab.preview && "italic")}>{tab.label}</span>
            {tab.detail ==
            <TrailingSlot tab={tab} active={selected} onClose={() => onClose(tab.id)} />
          </div>
        );
      })}
    </div>
  );
};

