export const DomainEvent = Schema.TaggedUnion({
  ...constellationEventFields,
  ...resourceEventFields,
  ...notificationEventFields,
  WorkspaceRegistered: { workspace: Workspace },
  WorkspaceUpdated: { workspace: Workspace },
