/**
 * The Client runtime in the main process: one Effect runtime holding
 * `@polaris/client`'s HostRegistry, the local Host plus the remote Hosts from
 * the settings, and the Host list (with Connection States) the renderers see.
 */
import { hostname } from "node:os";
import {
  type ClientIdentity,
  type ConnectionStatus,
  type HostConnection,
  type HostConnectionOptions,
  HostConnector,
  HostRegistry,
  HostTarget,
} from "@polaris/client";
import { Capability } from "@polaris/protocol";
import {
  Context,
  Effect,
  Equal,
  Fiber,
  Layer,
  ManagedRuntime,
  Option,
  Predicate,
  Schema,
  Stream,
  SubscriptionRef,
} from "effect";
import type { ConnectionStatusView, HostView, IpcError } from "../shared/api.ts";
import type { LocalDaemon } from "./localDaemon.ts";
import type { Machines } from "./machines/service.ts";
import type { RemoteHostSetting } from "./settings.ts";

export const LOCAL_HOST_KEY = "local";

export class UnknownHost extends Error {
  readonly _tag = "UnknownHost";

  constructor(readonly key: string) {
    super(`no Host "${key}"`);
  }
}

/** A Host as the settings describe it, before it connects. */
export interface HostEntry {
  readonly key: string;
  readonly label: string;
  readonly colour: string | null;
  readonly alias: string | null;
  readonly proofHarness: boolean;
  readonly target: HostTarget;
  /** The remote command's argv; null for the default (`~/.polaris/bin/current/polaris bridge`). */
  readonly remoteCommand: ReadonlyArray<string> | null;
  /** Screenshots and tests only: report this round trip instead of the measured one. */
  readonly simulatedLatencyMs: number | null;
}

export const statusView = (status: ConnectionStatus): ConnectionStatusView => ({
  state: status.state,
  failure:
    status.failure === null
      ? null
      : {
          kind: status.failure.kind,
          reason: status.failure.reason,
          detail: status.failure.detail,
        },
  attempt: status.attempt,
  since: status.since,
  nextAttemptAt: status.nextAttemptAt,
  host: status.host,
  capabilities: status.capabilities,
  epoch: status.epoch,
  latencyMs: status.latencyMs,
});

export const hostView = (entry: HostEntry, status: ConnectionStatus): HostView => ({
  key: entry.key,
  label: entry.label,
  colour: entry.colour,
  alias: entry.alias,
  proofHarness: entry.proofHarness,
  status: {
    ...statusView(status),
    latencyMs:
      entry.simulatedLatencyMs !== null && status.state === "connected"
        ? entry.simulatedLatencyMs
        : status.latencyMs,
  },
});

/** A Host on a local socket under its own name: screenshots and tests only (`POLARIS_DESKTOP_EXTRA_HOSTS`). */
export const ExtraHost = Schema.Struct({
  key: Schema.String.check(Schema.isMinLength(1)),
  label: Schema.String,
  socket: Schema.String,
  /** Pretend the link has this round trip ("Slow link" in screenshots). */
  latencyMs: Schema.optionalKey(Schema.Number),
});

export type ExtraHost = typeof ExtraHost.Type;

const decodeExtras = Schema.decodeUnknownOption(Schema.fromJsonString(Schema.Array(ExtraHost)));

export const extraHosts = (json: string | undefined): ReadonlyArray<ExtraHost> =>
  json === undefined || json === "" ? [] : Option.getOrElse(decodeExtras(json), () => []);

export interface HostEntriesInput {
  /** Null while the local Host is switched off on this machine. */
  readonly local: LocalDaemon | null;
  readonly remotes: ReadonlyArray<RemoteHostSetting>;
  readonly extras?: ReadonlyArray<ExtraHost>;
  /** The local Host's name; "This Mac" by default. */
  readonly localLabel?: string;
}

/** The local Host first, then the remote Hosts in settings order; duplicate aliases dropped. */
export const hostEntries = ({
  local,
  remotes,
  extras = [],
  localLabel = "This Mac",
}: HostEntriesInput): ReadonlyArray<HostEntry> => {
  const seen = new Set<string>([LOCAL_HOST_KEY]);

  const entries: Array<HostEntry> = local === null ? [] : [localEntry(local, localLabel)];

  for (const extra of extras) {
    if (seen.has(extra.key)) continue;
    seen.add(extra.key);
    entries.push({
      key: extra.key,
      label: extra.label,
      colour: null,
      alias: null,
      proofHarness: false,
      target: HostTarget.Local({ socketPath: extra.socket }),
      remoteCommand: null,
      simulatedLatencyMs: extra.latencyMs ?? null,
    });
  }

  for (const remote of remotes) {
    if (seen.has(remote.alias)) continue;
    seen.add(remote.alias);
    entries.push(remoteEntry(remote));
  }

  return entries;
};

export const localEntry = (local: LocalDaemon, label = "This Mac"): HostEntry => ({
  key: LOCAL_HOST_KEY,
  label,
  colour: null,
  alias: null,
  proofHarness: local.benchHarness,
  target: HostTarget.Local({ socketPath: local.socketPath }),
  remoteCommand: null,
  simulatedLatencyMs: null,
});

/** Splits a remote command line on whitespace; the remote shell parses it again anyway. */
export const remoteCommandArgv = (line: string | undefined): ReadonlyArray<string> | null => {
  const argv = (line ?? "")
    .trim()
    .split(/\s+/)
    .filter((part) => part !== "");

  return argv.length === 0 ? null : argv;
};

export const remoteEntry = (remote: RemoteHostSetting): HostEntry => ({
  key: remote.alias,
  label: remote.label ?? remote.alias,
  colour: remote.colour ?? null,
  alias: remote.alias,
  proofHarness: false,
  target: HostTarget.Ssh({ alias: remote.alias, forwardAgent: remote.forwardAgent ?? false }),
  remoteCommand: remoteCommandArgv(remote.remoteCommand),
});

export const clientIdentity = (version: string): ClientIdentity => ({
  name: "Polaris",
  version,
  deviceLabel: hostname().replace(/\.local$/, ""),
  capabilities: Capability.literals,
});

const replaceView = (views: ReadonlyArray<HostView>, view: HostView) => {
  const at = views.findIndex((v) => v.key === view.key);

  if (at === -1) return [...views, view];

  return views.map((v, i) => (i === at ? view : v));
};

export interface HostDirectoryInput {
  readonly entries: ReadonlyArray<HostEntry>;
  readonly identity: ClientIdentity;
}

/** The Hosts this app connects to, and their views for the renderers. */
export class HostDirectory extends Context.Service<
  HostDirectory,
  {
    /** The Host list, updated on every Connection State change. */
    readonly views: SubscriptionRef.SubscriptionRef<ReadonlyArray<HostView>>;
    readonly entry: (key: string) => HostEntry | undefined;
    readonly connection: (key: string) => Effect.Effect<HostConnection, UnknownHost>;
    /** Adds a Host, or replaces the one with the same key (reconnecting it). */
    readonly add: (entry: HostEntry) => Effect.Effect<void>;
    readonly remove: (key: string) => Effect.Effect<void>;
  }
>()("polaris/desktop/HostDirectory") {
  static readonly layer = ({ entries, identity }: HostDirectoryInput) =>
    Layer.effect(
      HostDirectory,
      Effect.gen(function* () {
        const registry = yield* HostRegistry;
        const views = yield* SubscriptionRef.make<ReadonlyArray<HostView>>([]);
        const byKey = new Map<string, HostEntry>();
        const trackers = new Map<string, Fiber.Fiber<void>>();
        const scope = yield* Effect.scope;

        const stop = (key: string) =>
          Effect.gen(function* () {
            const tracker = trackers.get(key);
            trackers.delete(key);

            if (tracker !== undefined) yield* Fiber.interrupt(tracker);
            yield* registry.remove(key);
          });

        const remove = (key: string) =>
          Effect.gen(function* () {
            byKey.delete(key);
            yield* stop(key);
            yield* SubscriptionRef.update(views, (current) => current.filter((v) => v.key !== key));
          });

        const sameTransport = (a: HostEntry, b: HostEntry) =>
          Equal.equals(a.target, b.target) &&
          (a.remoteCommand ?? []).join(" ") === (b.remoteCommand ?? []).join(" ");

        // A replaced Host keeps its place in the list; a new name alone doesn't reconnect it.
        const add = (entry: HostEntry) =>
          Effect.gen(function* () {
            const previous = byKey.get(entry.key);

            if (
              previous !== undefined &&
              trackers.has(entry.key) &&
              sameTransport(previous, entry)
            ) {
              byKey.set(entry.key, entry);
              yield* SubscriptionRef.update(views, (current) =>
                current.map((v) =>
                  v.key === entry.key ? { ...v, label: entry.label, colour: entry.colour } : v
                )
              );

              return;
            }

            yield* stop(entry.key);
            byKey.set(entry.key, entry);

            const options: HostConnectionOptions = {
              key: entry.key,
              name: entry.label,
              target: entry.target,
              identity,
              ssh: entry.remoteCommand === null ? {} : { remoteCommand: entry.remoteCommand },
            };

            const connection = yield* registry.add(options);

            const tracker = yield* connection.changes.pipe(
              Stream.runForEach((status) =>
                SubscriptionRef.update(views, (current) =>
                  replaceView(current, hostView(byKey.get(entry.key) ?? entry, status))
                )
              ),
              Effect.forkIn(scope)
            );

            trackers.set(entry.key, tracker);
          });

        for (const entry of entries) yield* add(entry);

        const connection = (key: string) =>
          Effect.flatMap(
            registry.get(key),
            Option.match({
              onNone: () => Effect.fail(new UnknownHost(key)),
              onSome: (found) => Effect.succeed(found),
            })
          );

        return HostDirectory.of({ views, entry: (key) => byKey.get(key), connection, add, remove });
      })
    ).pipe(Layer.provide(HostRegistry.layer), Layer.provide(HostConnector.layer));
}

/** The services the IPC handlers run on. */
export type ClientServices = HostDirectory | Machines;

export type ClientRuntime = ManagedRuntime.ManagedRuntime<ClientServices, never>;

/** Starts connecting to every Host; the runtime owns every connection until disposed. */
export const startClientRuntime = (
  input: HostDirectoryInput,
  machines: Layer.Layer<Machines, never, HostDirectory>
): ClientRuntime => ManagedRuntime.make(Layer.provideMerge(machines, HostDirectory.layer(input)));

/** Every failure crossing IPC becomes its tag and message; a refusal's message is its `reason`. */
export const toIpcError = (error: {
  readonly _tag: string;
  readonly message: string;
  readonly reason?: unknown;
}): IpcError => ({
  code: error._tag,
  message: Predicate.isString(error.reason) && error.message === "" ? error.reason : error.message,
});

/** Waits until the Host with `key` is first Connected. */
export const whenConnected = (key: string) =>
  HostDirectory.use((dir) =>
    SubscriptionRef.changes(dir.views).pipe(
      Stream.filter((views) => views.some((v) => v.key === key && v.status.state === "connected")),
      Stream.runHead,
      Effect.asVoid
    )
  );

/**
 * The Engine's shared state and primitives: the running Harnesses, terminal
 * followers and live item progress, per-session serialization, and `signal`,
 * which runs a lifecycle input through the session machine and commits it.
 * The other engine modules are built on one `EngineRuntime`.
 */
import type {
  DomainEvent,
  SessionId,
  TerminalLaunch,
  Turn,
  TurnId,
  SubagentId,
  TurnItem,
} from "@polaris/protocol";
import {
  Clock,
  Context,
  Duration,
  Effect,
  Exit,
  Fiber,
  FiberMap,
  Layer,
  Scope,
  Semaphore,
} from "effect";
import type { CheckpointPolicy } from "../git/prune.ts";
import type { HarnessDriver, HarnessSession } from "../harness/HarnessDriver.ts";
import {
  AttachmentStore,
  Checkpoints,
  HarnessRegistry,
  type ServiceError,
  WorktreeTracker,
} from "../services.ts";
import { type CommitResult, EventStore } from "../store/EventStore.ts";
import { waitingOnBackgroundWork } from "./session.backgroundTasks.ts";
import type { ReadModel, SessionRecord } from "../store/model.ts";
import { decideSession, type SessionEffect, type SessionInput } from "./session.ts";

export type SignalResult = CommitResult & { readonly effects: ReadonlyArray<SessionEffect> };

export interface EngineSettings {
  /** How long an Idle session keeps its Harness process before going Dormant. */
  readonly idleTimeout: Duration.Input;
  /** Maximum silence while an Idle session waits on background work; default two hours. */
  readonly backgroundIdleTimeout?: Duration.Input;
  /** Checkpoint pruning policy (`git/prune.ts`); `DEFAULT_CHECKPOINT_POLICY` when unset. */
  readonly checkpointPolicy?: CheckpointPolicy;
  /** How often the checkpoint sweeper runs (6 hours when unset); null turns it off. */
  readonly checkpointSweepInterval?: Duration.Input | null;
}

export const EngineConfig = Context.Reference<EngineSettings>(
  "polaris/daemon/engine/EngineConfig",
  {
    defaultValue: () => ({ idleTimeout: Duration.minutes(30) }),
  }
);

/** Something whose `HarnessEvent`s the engine consumes: a live Harness, or a terminal follower. */
export interface EventSource {
  readonly scope: Scope.Closeable;
  /** Set when Polaris stops the source on purpose, so its exit is not treated as a crash. */
  stopping: boolean;
}

export interface LiveHarness extends EventSource {
  readonly driver: HarnessDriver;
  readonly session: HarnessSession;
  consumer: Fiber.Fiber<void> | null;
}

/** Follows a session's terminal UI while it is In Terminal (sequential hand-off). */
export interface TerminalFollower extends EventSource {
  readonly driver: HarnessDriver;
  fiber: Fiber.Fiber<void> | null;
}

/** An item still in progress, as last reported by `ItemUpdated`. */
export interface Progress {
  readonly turnId: TurnId;
  readonly item: TurnItem;
  readonly subagentId: SubagentId | null;
}

/** Events the Daemon decides on its own, from the session's latest record and the model. */
export type DecideFor = (record: SessionRecord, model: ReadModel) => ReadonlyArray<DomainEvent>;

const make = Effect.gen(function* () {
  const store = yield* EventStore;
  const config = yield* EngineConfig;
  const clock = yield* Clock.Clock;
  const idleNow = () => Number(clock.monotonicTimeNanosUnsafe() / 1_000_000n);
  const engineScope = yield* Effect.scope;
  const live = new Map<SessionId, LiveHarness>();
  const progress = new Map<SessionId, Map<string, Progress>>();
  const idleTimers = yield* FiberMap.make<SessionId>();
  const sessionLocks = new Map<SessionId, Semaphore.Semaphore>();
  const now = Effect.map(Clock.currentTimeMillis, (ms) => new Date(ms).toISOString());

  const serially =
    (sessionId: SessionId) =>
    <A, E, R>(effect: Effect.Effect<A, E, R>): Effect.Effect<A, E, R> => {
      let lock = sessionLocks.get(sessionId);

      if (lock === undefined) {
        lock = Semaphore.makeUnsafe(1);
        sessionLocks.set(sessionId, lock);
      }

      return lock.withPermits(1)(effect);
    };

  const recordDecision = (
    sessionId: SessionId,
    f: (record: SessionRecord | undefined, model: ReadModel) => ReadonlyArray<DomainEvent>
  ) => {
    const activity = touchIdle(sessionId);

    const committed = store.commit({
      commandId: null,
      decide: (model) => {
        const record = model.sessions.get(sessionId);

        return Effect.succeed(f(record, model));
      },
    });

    return activity === null
      ? committed
      : committed.pipe(
          Effect.tap((result) =>
            "envelopes" in result && result.envelopes.length > 0 ? activity : Effect.void
          )
        );
  };

  const recordFor = (sessionId: SessionId, f: DecideFor) =>
    recordDecision(sessionId, (record, model) => (record === undefined ? [] : f(record, model)));

  const dropProgress = (sessionId: SessionId, turnId?: TurnId) => {
    const items = progress.get(sessionId);

    if (items === undefined) return;

    for (const [id, entry] of items)
      if (turnId === undefined || entry.turnId === turnId) items.delete(id);

    if (items.size === 0) progress.delete(sessionId);
  };

  const backgroundIdle = new Map<SessionId, { lastEvent: number }>();

  const cancelIdle = (sessionId: SessionId) => {
    backgroundIdle.delete(sessionId);

    return FiberMap.remove(idleTimers, sessionId);
  };

  const stopHarness = (sessionId: SessionId) =>
    Effect.gen(function* () {
      const entry = live.get(sessionId);

      if (entry === undefined) return;
      entry.stopping = true;
      backgroundIdle.delete(sessionId);
      live.delete(sessionId);
      dropProgress(sessionId);

      if (entry.consumer !== null) yield* Fiber.interrupt(entry.consumer);
      yield* Scope.close(entry.scope, Exit.void);
    });

  const signalWith = (
    sessionId: SessionId,
    input: (record: SessionRecord | undefined) => SessionInput
  ): Effect.Effect<SignalResult, ServiceError> =>
    Effect.gen(function* () {
      let effects: ReadonlyArray<SessionEffect> = [];

      const result = yield* recordDecision(sessionId, (record) => {
        const decision = decideSession(record, input(record));
        effects = decision.effects;

        return decision.events;
      });

      for (const effect of effects) {
        if (effect === "scheduleIdleStop") yield* scheduleIdle(sessionId);
        else if (effect === "stopHarness") yield* stopHarness(sessionId);
      }

      return { ...result, effects };
    });

  const signal = (sessionId: SessionId, input: SessionInput) => signalWith(sessionId, () => input);

  const goDormant = (sessionId: SessionId, backgroundExpired: boolean) =>
    Effect.sync(() => backgroundIdle.delete(sessionId))
      .pipe(
        Effect.andThen(
          Effect.flatMap(now, (at) =>
            signalWith(sessionId, () => ({
              type: "idle.timeout",
              harnessLive: live.has(sessionId),
              backgroundExpired,
              at,
            }))
          )
        )
      )
      .pipe(Effect.catchCause((cause) => Effect.logError("idle stop failed", cause)));

  const backgroundStop = (sessionId: SessionId, activity: { lastEvent: number }) =>
    Effect.gen(function* () {
      const timeout = Duration.toMillis(config.backgroundIdleTimeout ?? Duration.hours(8));
      let remaining = timeout;

      while (true) {
        yield* Effect.sleep(Duration.millis(remaining));

        const next = yield* serially(sessionId)(
          Effect.gen(function* () {
            if (backgroundIdle.get(sessionId) !== activity) return null;
            const delay = timeout - (idleNow() - activity.lastEvent);

            if (delay > 0) return delay;
            yield* goDormant(sessionId, true);

            return null;
          })
        );

        if (next === null) return;
        remaining = next;
      }
    });

  const touchIdle = (sessionId: SessionId) => {
    const activity = backgroundIdle.get(sessionId);

    return activity === undefined
      ? null
      : Effect.sync(() => {
          if (backgroundIdle.get(sessionId) === activity) activity.lastEvent = idleNow();
        });
  };

  const scheduleIdle = (sessionId: SessionId) =>
    Effect.gen(function* () {
      const record = (yield* store.model).sessions.get(sessionId);

      if (record === undefined) return;

      if (!waitingOnBackgroundWork(record)) {
        backgroundIdle.delete(sessionId);
        yield* FiberMap.run(
          idleTimers,
          sessionId,
          Effect.sleep(config.idleTimeout).pipe(
            Effect.andThen(serially(sessionId)(goDormant(sessionId, false)))
          )
        );

        return;
      }

      const at = idleNow();
      const existing = backgroundIdle.get(sessionId);

      if (existing !== undefined) {
        existing.lastEvent = at;

        return;
      }

      const activity = { lastEvent: at };
      backgroundIdle.set(sessionId, activity);
      yield* FiberMap.run(idleTimers, sessionId, backgroundStop(sessionId, activity));
    });

  const failSession = (sessionId: SessionId, message: string) =>
    Effect.gen(function* () {
      const at = yield* now;
      yield* Effect.logWarning(`session ${sessionId} failed: ${message}`);
      yield* signal(sessionId, { type: "session.fail", message, at });
    });

  const checkpoints = yield* Checkpoints;

  const capture = (sessionId: SessionId, turnId: TurnId, label: "before" | "after") =>
    Effect.gen(function* () {
      const model = yield* store.model;
      const record = model.sessions.get(sessionId);

      if (record === undefined) return null;

      return yield* checkpoints.capture({ cwd: record.session.cwd, sessionId, turnId, label });
    }).pipe(
      Effect.catch((error) =>
        Effect.logWarning(`checkpoint ${label} of ${turnId} failed: ${error.message}`).pipe(
          Effect.as(null)
        )
      )
    );

  const findTurn = (sessionId: SessionId, turnId: TurnId) =>
    Effect.gen(function* () {
      const record = (yield* store.model).sessions.get(sessionId);
      const recent = record?.turns.find((t) => t.id === turnId);

      if (recent !== undefined || record === undefined) return recent ?? null;

      const older = yield* store.readTurns({
        sessionId,
        beforeIndex: record.turns[0]?.index ?? null,
        limit: null,
      });

      return older.find((t) => t.id === turnId) ?? null;
    });

  const runtime: EngineRuntime["Service"] = {
    store,
    registry: yield* HarnessRegistry,
    checkpoints,
    worktrees: yield* WorktreeTracker,
    attachmentStore: yield* AttachmentStore,
    config,
    engineScope,
    live,
    terminalLaunch: new Map(),
    followers: new Map(),
    progress,
    now,
    serially,
    recordFor,
    dropProgress,
    signal,
    signalWith,
    failSession,
    capture,
    cancelIdle,
    touchIdle,
    stopHarness,
    findTurn,
  };

  return runtime;
});

/** The shared state and primitives of one Engine; built once per `Engine.layer`. */
export class EngineRuntime extends Context.Service<
  EngineRuntime,
  {
    readonly store: EventStore["Service"];
    readonly registry: HarnessRegistry["Service"];
    readonly checkpoints: Checkpoints["Service"];
    readonly worktrees: WorktreeTracker["Service"];
    readonly attachmentStore: AttachmentStore["Service"];
    readonly config: EngineSettings;
    /** Fibers forked here live as long as the Engine. */
    readonly engineScope: Scope.Scope;
    readonly live: Map<SessionId, LiveHarness>;
    readonly terminalLaunch: Map<SessionId, TerminalLaunch>;
    readonly followers: Map<SessionId, TerminalFollower>;
    /** Items in progress per session, so a Client that subscribes mid-Turn sees them. */
    readonly progress: Map<SessionId, Map<string, Progress>>;
    readonly now: Effect.Effect<string>;
    /** Reactor work and Harness lifecycle changes for one session run one at a time. */
    readonly serially: (
      sessionId: SessionId
    ) => <A, E, R>(effect: Effect.Effect<A, E, R>) => Effect.Effect<A, E, R>;
    /** Record events the Daemon decides on its own, against the session's latest state. */
    readonly recordFor: (
      sessionId: SessionId,
      f: DecideFor
    ) => Effect.Effect<CommitResult, ServiceError>;
    /** Forget progress of items that can no longer complete (their Turn ended, the Harness went away). */
    readonly dropProgress: (sessionId: SessionId, turnId?: TurnId) => void;
    /** Run one lifecycle input through the session machine, commit what it emits, run its effects. */
    readonly signal: (
      sessionId: SessionId,
      input: SessionInput
    ) => Effect.Effect<CommitResult, ServiceError>;
    /** `signal` with an input built from the record it is decided against. */
    readonly signalWith: (
      sessionId: SessionId,
      input: (record: SessionRecord | undefined) => SessionInput
    ) => Effect.Effect<SignalResult, ServiceError>;
    /** The Turn in flight fails and the session goes Failed. */
    readonly failSession: (
      sessionId: SessionId,
      message: string
    ) => Effect.Effect<void, ServiceError>;
    readonly capture: (
      sessionId: SessionId,
      turnId: TurnId,
      label: "before" | "after"
    ) => Effect.Effect<{ readonly ref: string; readonly commit: string } | null>;
    readonly touchIdle: (sessionId: SessionId) => Effect.Effect<void> | null;
    readonly cancelIdle: (sessionId: SessionId) => Effect.Effect<void>;
    /** Stop the Harness on purpose. Never call from the session's own event consumer. */
    readonly stopHarness: (sessionId: SessionId) => Effect.Effect<void>;
    /** A Turn of any age: recent ones are in memory, older ones in SQL. */
    readonly findTurn: (
      sessionId: SessionId,
      turnId: TurnId
    ) => Effect.Effect<Turn | null, ServiceError>;
  }
>()("polaris/daemon/engine/EngineRuntime") {
  static readonly layer = Layer.effect(EngineRuntime, make);
}

